using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change: HasData() no longer allows non-deterministic values
        // like DateTime.UtcNow. Use a fixed constant instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "CatalogDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change #1: Discriminator property renamed from "Discriminator" to "$type".
        // For existing documents that already use "Discriminator", explicitly configure
        // the old property name to avoid data mismatch.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Product>().ToContainer("Products");
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public string PartitionKey { get; set; } = default!;
}

// EF9 breaking change #2: Synchronous I/O on Cosmos DB is no longer supported.
// All queries must use async methods (ToListAsync, FirstOrDefaultAsync, etc.).
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (EF8 - now throws InvalidOperationException in EF9):
    //   var products = _db.Products.Where(p => p.Name == name).ToList();
    //
    // AFTER (EF9 fix - use async):
    public async Task<List<Product>> GetProductsByNameAsync(string name)
    {
        return await _db.Products
            .Where(p => p.Name == name)
            .ToListAsync();
    }
}

